	private long store(Value value) throws IOException {
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(value);
		valueStore.commit();
		assertNotEquals(LmdbValue.UNKNOWN_ID, id);
		return id;
	}

	private ValueStore openWithPersistedProperties() throws IOException {
		StoreProperties properties = new StoreProperties(dataDir);
		assertTrue(properties.load(), "fixture: store.properties must exist");
		ValueStore store = new ValueStore(new File(dataDir, "values"), properties, new LmdbStoreConfig());
		// LmdbStore.init persists the properties after the value and triple stores have been initialised
		properties.save();
		return store;
	}

	private StoreProperties loadProperties() {
		StoreProperties properties = new StoreProperties(dataDir);
		assertTrue(properties.load());
		return properties;
	}

	/** Writes a store.properties as a store created before the policy existed, plus the given policy (if any). */
	private void writeProperties(String languageTagKey) throws IOException {
		writeLmdbStoreProperties(dataDir, languageTagKey);
	}

	private static void writeLmdbStoreProperties(File dir, String languageTagKey) throws IOException {
		dir.mkdirs();
		Properties properties = new Properties();
		File file = new File(dir, StoreProperties.FILE_NAME);
		if (file.isFile()) {
			try (InputStream in = new FileInputStream(file)) {
				properties.load(in);
			}
		}
		properties.setProperty(StoreProperties.VERSION_KEY, String.valueOf(LmdbStore.VERSION));
		properties.setProperty(StoreProperties.INDEXES_KEY, "spoc,posc");
		properties.setProperty(StoreProperties.TRIPLE_TERM_INDEXES_KEY, "spoc,cspo");
		properties.remove(StoreProperties.LANGUAGE_TAG_KEY);
		if (languageTagKey != null) {
			properties.setProperty(StoreProperties.LANGUAGE_TAG_KEY, languageTagKey);
		}
		try (OutputStream out = new FileOutputStream(file)) {
			properties.store(out, "test fixture");
		}
		assertNull(languageTagKey == null ? new StoreProperties(dir).getLanguageTagKey() : null);
	}

	private static String languageTagKey(File dir) {
		StoreProperties properties = new StoreProperties(dir);
		assertTrue(properties.load(), "store.properties must exist");
		return properties.getLanguageTagKey();
	}

	private static SailRepository open(File dir) {
		SailRepository repository = new SailRepository(new LmdbStore(dir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		return repository;
	}

	private static void add(File dir, List<Statement> data) {
		SailRepository repository = open(dir);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(data);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static List<String> rows(RepositoryConnection connection, String query) {
		List<String> rows = new ArrayList<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				rows.add(render(result.next()));
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static String render(BindingSet bindingSet) {
		List<String> parts = new ArrayList<>();
		for (String name : new TreeSet<>(bindingSet.getBindingNames())) {
			Value value = bindingSet.getValue(name);
			if (value != null) {
				parts.add(name + "=" + NTriplesUtil.toNTriplesString(value));
			}
		}
		return String.join("|", parts);
	}

	private static IRI iri(String local) {
		return VF.createIRI(NS + local);
	}

	private static Statement st(String subject, String predicate, Value object) {
		return VF.createStatement(iri(subject), iri(predicate), object);
	}
